package com.clicklocked;
import net.runelite.client.config.*;
@ConfigGroup("clicklocked-challenge")
public interface ClicklockedConfig extends Config {
 @ConfigItem(keyName="xpPerClick", name="XP per click", description="Used when starting a NEW challenge. Existing challenge rules stay fixed.", position=0)
 @Range(min=1, max=1000000)
 default int xpPerClick() { return 100; }
 @ConfigItem(keyName="startingClicks", name="Starting clicks", description="Used when starting a NEW challenge.", position=1)
 @Range(min=0, max=1000000)
 default int startingClicks() { return 100; }
 @ConfigItem(keyName="countFKeys", name="Count F-key presses", description="Count F1-F12 attempts, including unbound keys. Camera arrow keys are free.", position=2)
 default boolean countFKeys() { return true; }
}

package com.clicklocked;
import java.awt.*;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.components.*;
public class ClicklockedOverlay extends OverlayPanel {
 private final ClicklockedPlugin plugin;
 @Inject ClicklockedOverlay(ClicklockedPlugin plugin) {
  this.plugin=plugin; setPosition(OverlayPosition.TOP_LEFT);
  panelComponent.setPreferredSize(new Dimension(205,0));
 }
 private void row(String name,String value,Color color) {
  panelComponent.getChildren().add(LineComponent.builder().left(name).right(value).rightColor(color).build());
 }
 @Override public Dimension render(Graphics2D graphics) {
  Ledger l=plugin.ledger();
  if (l==null) return null;
  panelComponent.getChildren().clear();
  panelComponent.getChildren().add(TitleComponent.builder().text(l.active ? "CLICKLOCKED" : "CLICKLOCKED • PAUSED").color(Color.ORANGE).build());
  row("Banked",String.format("%,d",l.banked()),l.banked()<=0?Color.RED:Color.GREEN);
  row("Used",String.format("%,d",l.used),Color.WHITE);
  row("Earned",String.format("%,d",l.earned()),Color.WHITE);
  row("Next click",l.nextXp()+" XP",Color.LIGHT_GRAY);
  row("Rate",l.xpPerClick+" XP / click",Color.LIGHT_GRAY);
  return super.render(graphics);
 }
}

package com.clicklocked;
import java.awt.BorderLayout;
import javax.swing.*;
import net.runelite.client.ui.PluginPanel;
final class ClicklockedPanel extends PluginPanel {
 final JLabel status=new JLabel("Log in, then start your challenge.");
 ClicklockedPanel(ClicklockedPlugin plugin) {
  setLayout(new BorderLayout(0,12));
  JPanel controls=new JPanel(); controls.setLayout(new BoxLayout(controls,BoxLayout.Y_AXIS));
  controls.add(new JLabel("CLICKLOCKED")); controls.add(Box.createVerticalStrut(12)); controls.add(status);
  JButton start=new JButton("Start / pause / resume");
  start.addActionListener(e->plugin.toggle()); controls.add(start);
  JButton adjust=new JButton("Correct banked clicks…");
  adjust.addActionListener(e->{
   String account=plugin.accountKey();
   if(account==null) return;
   String value=JOptionPane.showInputDialog(this,"Signed correction (+10 or -10). Does not alter clicks used or XP.");
   if(value!=null) try { plugin.adjust(account,Long.parseLong(value.trim())); }
   catch(NumberFormatException ex) { JOptionPane.showMessageDialog(this,"Enter a whole number."); }
  }); controls.add(adjust);
  JTextArea help=new JTextArea("Start AFTER Tutorial Island.\nRules lock when you start.\nZero clicks shows a red balance;\nthe plugin never blocks input.\nPause is for setup/testing only.\nProgress saves per account.");
  help.setEditable(false); help.setOpaque(false); controls.add(Box.createVerticalStrut(12)); controls.add(help);
  add(controls,BorderLayout.NORTH);
 }
 void update(String text) { SwingUtilities.invokeLater(()->status.setText(text)); }
}

package com.clicklocked;

import com.google.inject.Provides;
import com.google.gson.Gson;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.*;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.*;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(name="Clicklocked", description="Earn clicks with XP; track a persistent challenge balance", tags={"clicks","ironman","restricted"})
public class ClicklockedPlugin extends Plugin implements MouseListener, KeyListener {
 private static final String GROUP="clicklocked-challenge";
 @Inject private Client client;
 @Inject private ClientThread clientThread;
 @Inject private ConfigManager configManager;
 @Inject private ClicklockedConfig config;
 @Inject private Gson gson;
 @Inject private MouseManager mouseManager;
 @Inject private KeyManager keyManager;
 @Inject private OverlayManager overlayManager;
 @Inject private ClicklockedOverlay overlay;
 @Inject private ClientToolbar toolbar;
 private ClicklockedPanel panel;
 private NavigationButton nav;
 private volatile Ledger state;
 private volatile String account;
 private boolean loadFailed;
 private volatile boolean[] keyboardCosts=new boolean[KeyEvent.KEY_LAST+1];
 @Provides ClicklockedConfig provideConfig(ConfigManager manager) { return manager.getConfig(ClicklockedConfig.class); }
 Ledger ledger() { return state; }
 String accountKey() { return account; }
 @Override protected void startUp() {
  panel=new ClicklockedPanel(this);
  BufferedImage icon=new BufferedImage(16,16,BufferedImage.TYPE_INT_ARGB);
  Graphics2D g=icon.createGraphics();g.setColor(Color.ORANGE);g.fillOval(1,1,14,14);g.setColor(Color.BLACK);g.drawString("C",4,12);g.dispose();
  nav=NavigationButton.builder().tooltip("Clicklocked").icon(icon).panel(panel).priority(8).build();
  toolbar.addNavigation(nav);overlayManager.add(overlay);mouseManager.registerMouseListener(this);keyManager.registerKeyListener(this);
  clientThread.invoke(()->{ if(loggedIn()) attach(); });
 }
 @Override protected void shutDown() {
  mouseManager.unregisterMouseListener(this);keyManager.unregisterKeyListener(this);overlayManager.remove(overlay);toolbar.removeNavigation(nav);
  clientThread.invoke(()->{save();state=null;account=null;});
 }
 private boolean loggedIn() { return client.getGameState()==GameState.LOGGED_IN && client.getLocalPlayer()!=null; }
 private void attach() {
  if(!loggedIn()) return;
  if(client.getAccountHash()==-1L) return;
  String key="account-"+Long.toUnsignedString(client.getAccountHash());
  if(key.equals(account)) return;
  save(); state=null; account=key; loadFailed=false;
  String json=configManager.getConfiguration(GROUP,key);
  if(json!=null) {
   try { Ledger loaded=gson.fromJson(json,Ledger.class); loaded.validate(); state=loaded; }
   catch(RuntimeException ex) { loadFailed=true; panel.update("Save unreadable; tracking stopped."); return; }
  }
  // Catch XP earned during disconnects. Paused challenges only update their baseline.
  if(state!=null) { state.observe(client.getOverallExperience()); save(); }
  updatePanel();
 }
 private void save() { if(state!=null && account!=null) configManager.setConfiguration(GROUP,account,gson.toJson(state)); }
 private void updatePanel() {
  if(panel!=null && !loadFailed) panel.update(state==null?"Ready to start after Tutorial Island.":state.active?"Tracking • "+state.banked()+" banked":"Paused • "+state.banked()+" banked");
 }
 void toggle() { clientThread.invoke(()->{
  if(!loggedIn()) return; attach(); if(loadFailed) return;
  if(state==null) state=new Ledger(config.xpPerClick(),config.startingClicks(),client.getOverallExperience());
  else { state.observe(client.getOverallExperience()); state.active=!state.active; }
  save();updatePanel();
 }); }
 void adjust(String expectedAccount,long delta) { clientThread.invoke(()->{
  if(!loggedIn()) return; attach();
  if(state!=null && expectedAccount.equals(account)) {
   state.adjustment=Math.addExact(state.adjustment,delta);save();updatePanel();
  }
 }); }
 @Subscribe public void onGameTick(GameTick e) {
  attach(); if(state!=null && loggedIn()) { state.observe(client.getOverallExperience()); escapeCosts=hasClosableRoot();save();updatePanel(); }
 }
 @Subscribe public void onGameStateChanged(GameStateChanged e) {
  if(e.getGameState()==GameState.LOGIN_SCREEN) { save();state=null;account=null;updatePanel(); }
 }
 private void spend(String expected) {
  if(expected!=null && expected.equals(account) && state!=null && loggedIn()) {
   state.spend(); save();updatePanel();
  }
 }
 // Cache interface context on the client thread BEFORE native key events are processed.
 @Subscribe public void onClientTick(ClientTick e) {
  boolean[] costs=new boolean[KeyEvent.KEY_LAST+1];
  if(loggedIn() && state!=null && state.active) {
   int[] keys={KeyEvent.VK_SPACE,KeyEvent.VK_ENTER,KeyEvent.VK_ESCAPE,
    KeyEvent.VK_1,KeyEvent.VK_2,KeyEvent.VK_3,KeyEvent.VK_4,KeyEvent.VK_5,
    KeyEvent.VK_6,KeyEvent.VK_7,KeyEvent.VK_8,KeyEvent.VK_9};
   for(int key:keys) if(key!=KeyEvent.VK_ESCAPE) costs[key]=keyCosts(key);
   // Modal detection is cached separately once per game tick.
   costs[KeyEvent.VK_ESCAPE]=escapeCosts;
   if(config.countFKeys()) for(int key=KeyEvent.VK_F1;key<=KeyEvent.VK_F12;key++) costs[key]=true;
  }
  keyboardCosts=costs;
 }
 private boolean escapeCosts;
 @Override public MouseEvent mousePressed(MouseEvent e) {
  if(e.getButton()==MouseEvent.BUTTON1 || e.getButton()==MouseEvent.BUTTON3) {
   String expected=account;
   if(expected!=null && state!=null && state.active && !overlay.getBounds().contains(e.getPoint()))
    clientThread.invoke(()->spend(expected));
  }
  return e;
 }
 // Only listen to the game canvas. No MenuOptionClicked listener: that would count mouse actions twice.
 @Override public void keyPressed(KeyEvent e) {
  int key=e.getKeyCode();
  String expected=account;
  boolean[] costs=keyboardCosts;
  if(!e.isConsumed() && key>=0 && key<costs.length && costs[key]) clientThread.invoke(()->spend(expected));
 }
 private boolean visible(int id) { Widget w=client.getWidget(id);return w!=null && !w.isHidden(); }
 private boolean keyCosts(int key) {
  if(!loggedIn() || state==null || !state.active) return false;
  if(config.countFKeys() && key>=KeyEvent.VK_F1 && key<=KeyEvent.VK_F12) return true;
  if(key==KeyEvent.VK_SPACE && (visible(InterfaceID.ChatLeft.CONTINUE) || visible(InterfaceID.ChatRight.CONTINUE)
    || visible(InterfaceID.Messagebox.CONTINUE) || visible(InterfaceID.LevelupDisplay.CONTINUE))) return true;
  if(key>=KeyEvent.VK_1 && key<=KeyEvent.VK_9 && visible(InterfaceID.Chatmenu.OPTIONS)) {
   Widget options=client.getWidget(InterfaceID.Chatmenu.OPTIONS);
   Widget[] children=options.getChildren();
   // Child zero is the prompt; following children are numbered options.
   return children!=null && key-KeyEvent.VK_1+1<children.length;
  }
  // Native amount/name/object entry dialogs. Chat, PM and search typing are excluded.
  int mode=client.getVarcIntValue(VarClientID.MESLAYERMODE);
  if(key==KeyEvent.VK_ENTER && (mode==1 || mode==2 || mode==3 || mode==7 || mode==8)) return true;
  // Escape costs one when closing a modal interface, not when pressed in the open world.
  return key==KeyEvent.VK_ESCAPE && hasClosableRoot();
 }
 private boolean hasClosableRoot() {
  // A visible close button identifies a closable interface, without hardcoded interface IDs.
  Widget[] roots=client.getWidgetRoots();
  if(roots==null) return false;
  for(Widget root:roots) if(root!=null && closeButton(root,0)) return true;
  return false;
 }
 private boolean closeButton(Widget w,int depth) {
  if(depth>4 || w.isHidden()) return false;
  String[] actions=w.getActions();
  if(actions!=null) for(String action:actions) if("Close".equalsIgnoreCase(action)) return true;
  Widget[][] lists={w.getStaticChildren(),w.getDynamicChildren(),w.getNestedChildren()};
  for(Widget[] list:lists) if(list!=null) for(Widget child:list) if(child!=null && closeButton(child,depth+1)) return true;
  return false;
 }
 @Override public void keyReleased(KeyEvent e) { }
 @Override public void keyTyped(KeyEvent e) { }
 @Override public MouseEvent mouseClicked(MouseEvent e) { return e; }
 @Override public MouseEvent mouseReleased(MouseEvent e) { return e; }
 @Override public MouseEvent mouseEntered(MouseEvent e) { return e; }
 @Override public MouseEvent mouseExited(MouseEvent e) { return e; }
 @Override public MouseEvent mouseDragged(MouseEvent e) { return e; }
 @Override public MouseEvent mouseMoved(MouseEvent e) { return e; }
}

package com.clicklocked;
/** Pure accounting; serialized as one record per OSRS account. */
final class Ledger {
 int version = 1;
 int xpPerClick;
 long allowance;
 long gainedXp;
 long used;
 long adjustment;
 long lastXp;
 boolean active;
 Ledger(int rate, long starting, long baseline) {
  if (rate < 1 || starting < 0 || baseline < 0) throw new IllegalArgumentException();
  xpPerClick=rate; allowance=starting; lastXp=baseline; active=true;
 }
 long earned() { return gainedXp / xpPerClick; }
 long banked() { return allowance + earned() + adjustment - used; }
 long nextXp() { return xpPerClick - gainedXp % xpPerClick; }
 void observe(long xp) {
  if (xp < 0) return;
  if (active && xp > lastXp) gainedXp += xp - lastXp;
  lastXp=xp;
 }
 void spend() { if (active) used++; }
 void validate() {
  if (version!=1 || xpPerClick<1 || allowance<0 || gainedXp<0 || used<0 || lastXp<0)
   throw new IllegalArgumentException("Unsupported or invalid saved challenge");
 }
}

