package com.clicklocked;
import org.junit.Test;
import static org.junit.Assert.*;
public class LedgerTest {
 @Test public void remainderAndMultipleUnlocks() {
  Ledger l=new Ledger(100,100,1154);l.observe(1204);assertEquals(0,l.earned());assertEquals(50,l.nextXp());
  l.observe(1504);assertEquals(3,l.earned());assertEquals(103,l.banked());assertEquals(50,l.nextXp());
 }
 @Test public void noDoubleCountAndNegativeBalanceVisible() {
  Ledger l=new Ledger(100,1,0);l.observe(100);l.observe(100);assertEquals(1,l.earned());
  l.spend();l.spend();l.spend();assertEquals(-1,l.banked());
 }
 @Test public void pauseDoesNotEarnOrSpend() {
  Ledger l=new Ledger(100,10,0);l.active=false;l.observe(1000);l.spend();assertEquals(10,l.banked());
  l.active=true;l.observe(1100);assertEquals(1,l.earned());
 }
 @Test public void correctionDoesNotRewriteHistory() {
  Ledger l=new Ledger(100,10,0);l.spend();l.adjustment=-4;assertEquals(5,l.banked());assertEquals(1,l.used);
 }
 @Test public void initialXpDoesNotEarnClicks() {
  Ledger l=new Ledger(100,10,1000000);l.observe(1000000);assertEquals(0,l.earned());
 }
}
